-- I haven't updated yet but prepared
-- source=~/.config/hypr/env.conf

-- Monitor: reserve space for eww bar
-- Generated by hyprlang2lua. Review TODOs before reloading Hyprland.

hl.monitor({
    output = "eDP-1",
    mode = "1920x1080@60",
    position = "0x0",
    scale = "1",
})

hl.monitor({
    output = "eDP-1",
    addreserved = { top = 1, bottom = 1, left = 61, right = 1 },
})

hl.monitor({
    output = "HDMI-A-1",
    mode = "1920x1080@60",
    position = "1920x0",
    scale = "1",
    mirror = "eDP-1",
})

--################### Core components (authentication, idle daemon and stuff) ##############
