require("execs")

--############################ Keybinds ############################
-- Source: ~/.config/hypr/keybinds.conf — convert this file to Lua and ensure it is on Lua's package.path.
require("keybinds")

--############################# Input ##############################

hl.curve("md3_standard", { type = "bezier", points = { { 0.2, 0.0 }, { 0, 1.0 } } })
hl.curve("md3_decel", { type = "bezier", points = { { 0.05, 0.7 }, { 0.1, 1 } } })
hl.curve("md3_accel", { type = "bezier", points = { { 0.3, 0 }, { 0.8, 0.15 } } })
hl.curve("overshot", { type = "bezier", points = { { 0.05, 0.9 }, { 0.1, 1.05 } } })
hl.curve("hyprnostretch", { type = "bezier", points = { { 0.05, 0.9 }, { 0.1, 1.0 } } })
hl.curve("win10", { type = "bezier", points = { { 0, 0 }, { 0, 1 } } })
hl.curve("gnome", { type = "bezier", points = { { 0, 0.85 }, { 0.3, 1 } } })
hl.curve("funky", { type = "bezier", points = { { 0.46, 0.35 }, { -0.2, 1.2 } } })
hl.animation({
    leaf = "windows",
    enabled = true,
    speed = 2,
    bezier = "md3_decel",
    style = "slide",
})
hl.animation({
    leaf = "border",
    enabled = true,
    speed = 10,
    bezier = "default",
})
hl.animation({
    leaf = "fade",
    enabled = true,
    speed = 0.0000001,
    bezier = "default",
})
hl.animation({
    leaf = "workspaces",
    enabled = true,
    speed = 4,
    bezier = "md3_decel",
    style = "slidevert",
})

hl.window_rule({
    match = {
        class = "^(steam)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "^(guifetch)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "title:^(Open File)(.*)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "title:^(Open Folder)(.*)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "title:^(Save As)(.*)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "title:^(Library)(.*)$",
    },
    float = true,
})

hl.window_rule({
    match = {
        class = "^com.github.hluk.copyq$",
    },
    float = true,
})

hl.window_rule({
    match = {
        float = 1,
    },
    rounding = 10,
})

hl.layer_rule({
    match = { namespace = "gtk-layer-shell" },
    blur = true,
    -- TODO: manual review — unmapped layer rule: "ignorezero"
})

hl.layer_rule({
    match = { namespace = "waybar" },
    blur = true,
    -- TODO: manual review — unmapped layer rule: "ignorezero"
})

